mapper.update:
UPDATE agent_task
SET status = #{status}, result = #{result}, error = #{error},
    started_at = #{startedAt}, finished_at = #{finishedAt}
WHERE id = #{id}

mapper.select:
SELECT id, conversation_id, prompt, python_run_id, status, result, error,
       created_at, started_at, finished_at
FROM agent_task WHERE id = #{taskId}
